// frontend/src/components/Search.js

import React, { useState, useContext } from "react";
import flask from "../utils/axiosFlask"; // connects to http://localhost:5001
import axios from "../utils/axiosInstance"; // connects to your DB API
import GeneralContext from "./GeneralContext";
import "../styles/Search.css"; // Make sure styling exists

const Search = () => {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState([]);
  const { refreshAll } = useContext(GeneralContext);

  const handleChange = async (e) => {
    const value = e.target.value;
    setQuery(value);

    if (value.length < 2) {
      setResults([]);
      return;
    }

    try {
      const res = await flask.get(`/search?q=${value}`);
      setResults(res.data); // [{ symbol, name, exchange }]
    } catch (err) {
      console.error("Search failed:", err.message);
    }
  };

  const handleAddToWatchlist = async (symbol) => {
    try {
      await axios.post("/api/watchlist", { symbol }); // your backend DB API
      refreshAll(); // reload watchlist
      setQuery("");
      setResults([]);
    } catch (err) {
      console.error("Failed to add to watchlist:", err.message);
    }
  };

  return (
    <div className="search-wrapper">
      <input
        type="text"
        value={query}
        onChange={handleChange}
        placeholder="Search stocks (eg: RELIANCE, INFY, SBIN)"
        className="search-input"
      />

      {results.length > 0 && (
        <ul className="search-results">
          {results.map((stock, index) => (
            <li key={index} className="search-item">
              <div>
                <strong>{stock.symbol}</strong> — {stock.name}
                {stock.exchange && (
                  <span className="exchange"> ({stock.exchange})</span>
                )}
              </div>
              <button
                className="add-btn"
                onClick={() => handleAddToWatchlist(stock.symbol)}>
                +
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default Search;
